node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check for cart items for cust_001
console.log('=== CART for cust_001 ===');
const carts = db.prepare('SELECT * FROM carts WHERE user_id=?').all('cust_001');
carts.forEach(c => console.log(JSON.stringify(c, null, 2)));

console.log('\n=== CART ITEMS for cust_001 ===');
const cartItems = db.prepare('SELECT ci.* FROM cart_items ci JOIN carts c ON ci.cart_id=c.cart_id WHERE c.user_id=?').all('cust_001');
cartItems.forEach(i => console.log(JSON.stringify(i, null, 2)));

// If no carts tied to cust_001, show all carts
if (carts.length === 0) {
  console.log('\n=== ALL CARTS ===');
  db.prepare('SELECT * FROM carts').all().forEach(c => console.log(JSON.stringify(c, null, 2)));
  console.log('\n=== ALL CART ITEMS ===');
  db.prepare('SELECT * FROM cart_items').all().forEach(i => console.log(JSON.stringify(i, null, 2)));
}

db.close();
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check schema for carts and cart_items
console.log('=== CARTS SCHEMA ===');
const ci = db.prepare(\"PRAGMA table_info(carts)\").all();
ci.forEach(c => console.log(c.name, c.type));

console.log('\n=== CART_ITEMS SCHEMA ===');
const cii = db.prepare(\"PRAGMA table_info(cart_items)\").all();
cii.forEach(c => console.log(c.name, c.type));

console.log('\n=== ALL CARTS ===');
db.prepare('SELECT * FROM carts').all().forEach(c => console.log(JSON.stringify(c)));

console.log('\n=== ALL CART_ITEMS ===');
db.prepare('SELECT * FROM cart_items').all().forEach(c => console.log(JSON.stringify(c)));

db.close();
"

